package model;
public class Roles {
 public static class Admin extends User { private String adminType; public Admin(String i,String p,String n,String e,String c,String a){super(i,p,n,e,c);adminType=a;} public String getAdminType(){return adminType;} public void setAdminType(String v){adminType=v;} public String getRole(){return "Admin";} }
 public static class Doctor extends User { private String specialist,educationalInformation; public Doctor(String i,String p,String n,String e,String c,String s,String edu){super(i,p,n,e,c);specialist=s;educationalInformation=edu;} public String getSpecialist(){return specialist;} public void setSpecialist(String v){specialist=v;} public String getEducationalInformation(){return educationalInformation;} public void setEducationalInformation(String v){educationalInformation=v;} public String getRole(){return "Doctor";} }
 public static class Patient extends User { private String gender,address; private int age; public Patient(String i,String p,String n,String e,String c,String g,int a,String ad){super(i,p,n,e,c);gender=g;age=a;address=ad;} public String getGender(){return gender;} public void setGender(String v){gender=v;} public int getAge(){return age;} public void setAge(int v){age=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getRole(){return "Patient";} }
 public static class Receptionist extends User { private String receptionistId,address; public Receptionist(String i,String p,String n,String e,String c,String r,String a){super(i,p,n,e,c);receptionistId=r;address=a;} public String getReceptionistId(){return receptionistId;} public void setReceptionistId(String v){receptionistId=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getRole(){return "Receptionist";} }
 public static class Nurse extends User { private String nurseId,qualification,department; public Nurse(String i,String p,String n,String e,String c,String ni,String q,String d){super(i,p,n,e,c);nurseId=ni;qualification=q;department=d;} public String getNurseId(){return nurseId;} public void setNurseId(String v){nurseId=v;} public String getQualification(){return qualification;} public void setQualification(String v){qualification=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public String getRole(){return "Nurse";} }
}
